<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor\DcrInitialAccessTokenRevokedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenRevokedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withRevokedAt,
 * getRevokedAt/revokedAt accessors, and isRevokedAtChanged with/without original.
 */
class DcrInitialAccessTokenRevokedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRevokedAt creates a new instance with the RevokedAt set
     * from a string value, and getRevokedAt returns the primitive string.
     */
    public function testWithRevokedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenRevokedAtAccessorUnitTest();

        // Act
        $result = $holder->withRevokedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getRevokedAt());
    }
    /**
     * Asserts that withrevokedAt has access to the value object
     * from a string value, and getRevokedAt returns the primitive string.
     */
    public function testWithRevokedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenRevokedAtAccessorUnitTest();

        // Act
        $result = $holder->withRevokedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->revokedAt()->value());
    }
    public function testChangedRevokedAt(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenRevokedAtAccessorUnitTest();
        $original = $holder->withRevokedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withRevokedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withRevokedAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isRevokedAtChanged();
        $withSame = $original->isRevokedAtChanged($same);
        $withDiferent = $original->isRevokedAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithDcrInitialAccessTokenRevokedAtAccessorUnitTest
{
    use DcrInitialAccessTokenRevokedAtAccessor;
}
